alternate:
: > priority.txt
: > regular.txt
priority=0
regular=0
ignored=0
rejected=0
while read -r record || test -n "$record"; do
    case "$record" in
        ship:*)
            case "$record" in
                ship:|ship:urgent:) printf 'Cannot route: %s\n' "$record" >&2; rejected=$((rejected+1)) ;;
                ship:urgent:*) printf '%s\n' "$record" >> priority.txt; priority=$((priority+1)) ;;
                *) printf '%s\n' "$record" >> regular.txt; regular=$((regular+1)) ;;
            esac
            ;;
        collect:*)
            case "$record" in
                collect:) printf 'Cannot route: %s\n' "$record" >&2; rejected=$((rejected+1)) ;;
                *) printf '%s\n' "$record" >> regular.txt; regular=$((regular+1)) ;;
            esac
            ;;
        ''|hold:*) ignored=$((ignored+1)) ;;
        *) printf 'Cannot route: %s\n' "$record" >&2; rejected=$((rejected+1)) ;;
    esac
done < "$1"
printf 'Priority: %s\nRegular: %s\nIgnored: %s\nRejected: %s\n' "$priority" "$regular" "$ignored" "$rejected"
if test "$rejected" -gt 0; then exit 1; fi
exit 0
